import subprocess,json,sys
cmd=['sudo','-n','/srv/projects/skill-universal/runtimes/python3.12/bin/python3.12',
 '/srv/projects/Vivoapk/source/infra/upgrade_live_preview.py']
sha='578f0454f8a4ef2e6dbeefb11eb0089afe5dd5d0'
ret={'task':'VivoAPK guarded HLS pilot hygiene rollout','target_sha':sha,'pipeline':'preflight_then_atomic_upgrade'}
try:
    p=subprocess.run(cmd+['preflight','--sha',sha],capture_output=True,text=True,timeout=45)
    try: pre=json.loads(p.stdout.strip().splitlines()[-1])
    except Exception: pre={'status':'output_unparseable'}
    ret['preflight_status']=pre.get('status')
    if p.returncode or pre.get('status')!='pass':
        ret['status']='blocked_preflight';ret['reason']=pre.get('reason','preflight_failed')
    else:
        run=subprocess.run(cmd+['activate','--sha',sha],capture_output=True,text=True,timeout=205)
        try: act=json.loads(run.stdout.strip().splitlines()[-1])
        except Exception: act={'status':'output_unparseable'}
        ret['rollout_status']=act.get('status')
        ret['changed']=bool(act.get('changed'))
        ret['protected_pink_unchanged']=act.get('pink_modified') is False
        ret['new_stream_proxy_installed']=act.get('stream_proxy_installed')
        ret['rollback_reported']=act.get('status')=='rolled_back_after_failure'
        if act.get('status')=='pilot_enabled' and run.returncode==0:
            ret['status']='passed'
        else:
            ret['status']='blocked_or_rollback';ret['reason']=act.get('reason','rollout_not_verified')
except subprocess.TimeoutExpired:
    ret['status']='blocked_timeout'
except Exception as e:
    ret['status']='blocked_exception';ret['reason']=type(e).__name__
print(json.dumps(ret,sort_keys=True))
sys.exit(0 if ret.get('status')=='passed' else 2)
